findings.codeql_raw_query:
/**
 * @name Dangerous use of eval/exec (dataflow)
 * @description Track remote user input flowing into eval/exec (CWE-94)
 * @kind path-problem
 * @problem.severity error
 * @id py/remote-to-eval-exec
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module EvalExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      sink = ce.getCode()
    )
  }
}

module EvalExecFlow = TaintTracking::Global<EvalExecConfig>;
import EvalExecFlow::PathGraph

from EvalExecFlow::PathNode source, EvalExecFlow::PathNode sink
where EvalExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into eval/exec (or similar) here from $@.", source.getNode(), "remote input"
